corpus_block("test-position_dodge.R: can control whether to preserve total or individual width", {
  df <- data_frame(x = c("a", "b", "b"), y = c("a", "a", "b"))
  .plot("test-position_dodge.R: can control whether to preserve total or individual width #1", p_total <- ggplot(df, aes(x, fill = y)) +
      geom_bar(position = position_dodge(preserve = "total"), width = 1))
  .plot("test-position_dodge.R: can control whether to preserve total or individual width #2", p_single <- ggplot(df, aes(x, fill = y)) +
      geom_bar(position = position_dodge(preserve = "single"), width = 1))
})

corpus_block("test-position_dodge.R: position_dodge() can dodge points vertically", {
  df <- data.frame(x = c(1, 2, 3, 4), y = c("a", "a", "b", "b"))
  .plot("test-position_dodge.R: position_dodge() can dodge points vertically #1", horizontal <- ggplot(df, aes(y, x, group = seq_along(x))) +
      geom_point(position = position_dodge(width = 1, orientation = "x")))
  .plot("test-position_dodge.R: position_dodge() can dodge points vertically #2", vertical <- ggplot(df, aes(x, y, group = seq_along(x))) +
      geom_point(position = position_dodge(width = 1, orientation = "y")))
})

corpus_block("test-position_dodge.R: position_dodge() can reverse the dodge order", {
  df <- data.frame(x = c(1, 2, 2, 3, 3), group = c("A", "A", "B", "B", "C"))
  .plot("test-position_dodge.R: position_dodge() can reverse the dodge order #1", p <- ggplot(df, aes(x, y = 1, fill = group, label = group)))
  .plot("test-position_dodge.R: position_dodge() can reverse the dodge order #2", p + geom_col(position = position_dodge(reverse = TRUE)))
  ld <- get_layer_data(p + geom_col(position = position_dodge(reverse = TRUE)))
  .plot("test-position_dodge.R: position_dodge() can reverse the dodge order #3", p + geom_col(position = position_dodge(reverse = FALSE)))
  ld <- get_layer_data(p + geom_col(position = position_dodge(reverse = FALSE)))
})

corpus_block("test-position_dodge.R: position_dodge() can use the order aesthetic", {
  major <- c(1,1,1,2,2,3,3,4,4,5,6,7)
  minor <- c(1:3, 1:2, 1, 3, 2:3, 1:3)
  df <- data_frame0(
      x = LETTERS[major],
      g = c("X", "Y", "Z")[minor]
    )
  .plot("test-position_dodge.R: position_dodge() can use the order aesthetic #1", ggplot(df, aes(x, 1, colour = g, order = g)) + geom_point(position = position_dodge(preserve = "single", 
      width = 0.6)))
  ld <- layer_data(
      ggplot(df, aes(x, 1, colour = g, order = g)) +
        geom_point(position = position_dodge(preserve = "single", width = 0.6))
    )
})

